SELECT COALESCE(-SUM(amount), 0) AS total_refunded
FROM payments
WHERE amount < 0;

SELECT ROUND(
  (
    (SELECT SUM(amount) FROM payments WHERE strftime('%Y-%m', datetime(paid_at_utc, '+5 hours 30 minutes')) = '2026-09')
    -
    (SELECT SUM(amount) FROM payments WHERE strftime('%Y-%m', datetime(paid_at_utc, '+5 hours 30 minutes')) = '2026-08')
  )
  /
  (SELECT SUM(amount) FROM payments WHERE strftime('%Y-%m', datetime(paid_at_utc, '+5 hours 30 minutes')) = '2026-08'),
  4
) AS mom_growth;
